@api_view(['POST'])
@permission_classes([])
@csrf_exempt
def simulate_prediction(request):
    try:
        data = json.loads(request.body)
    except json.JSONDecodeError:
        return JsonResponse({'error': 'Invalid JSON'}, status=400)
    disease_type = data.get('disease_type')
    parameters = data.get('parameters', {})
    if not disease_type or not parameters:
        return JsonResponse({'error': 'Missing disease_type or parameters'}, status=400)
    ml_result = ai_service._predict_using_ml(disease_type, parameters)
    if ml_result is not None:
        score = ml_result['score']
        factors = ml_result['factors']
    else:
        fallback = ai_service._get_fallback_prediction(disease_type, parameters, 'ML unavailable')
        score = fallback['risk_score']
        factors = fallback.get('factors', [])
    level = 'CRITICAL' if score > 80 else ('HIGH' if score > 55 else ('MODERATE' if score > 30 else 'LOW'))
    return JsonResponse({'simulated_score': score, 'simulated_level': level, 'factors': factors}, status=200)
