@api_view(['GET'])
@permission_classes([IsAuthenticated])
def pathology_trends(request):
    try:
        patient = Patient.objects.get(user=request.user)
    except Patient.DoesNotExist:
        return JsonResponse({'trends': {}}, status=200)
    reports = patient.pathology_reports.all().order_by('created_at')
    trends = {}
    for report in reports:
        try:
            biomarkers = json.loads(report.report_data or '[]')
        except Exception:
            continue
        date_str = report.created_at.strftime('%Y-%m-%d')
        for bm in biomarkers:
            if not bm.get('name') or bm.get('value') is None:
                continue
            name = bm['name'].strip()
            key = name.lower()
            try:
                val = float(bm['value'])
            except (ValueError, TypeError):
                continue
            if key not in trends:
                trends[key] = {'display_name': name, 'unit': bm.get('unit',''), 'data': []}
            trends[key]['data'].append({'date': date_str, 'value': val, 'source_id': report.id})
    return JsonResponse({'trends': trends}, status=200)
