@api_view(['POST'])
@permission_classes([])
@csrf_exempt
def explain_result(request):
    try:
        data = json.loads(request.body)
    except json.JSONDecodeError:
        return JsonResponse({'error': 'Invalid JSON'}, status=400)
    text = data.get('text', '').strip()
    language = data.get('language', 'en')
    if not text:
        return JsonResponse({'error': 'No text provided'}, status=400)
    if language == 'en':
        return JsonResponse({'explanation': text}, status=200)
    lang_names = {'ta': 'Tamil', 'hi': 'Hindi'}
    lang_name = lang_names.get(language, 'English')
    prompt = f'Translate and explain the following medical text in {lang_name}. Preserve all numbers, units, medication names, and medical values exactly as they appear. Do not change numeric values. Return only the translated explanation: {text}'
    try:
        result = run_async(llm_provider.generate_response(
            prompt=prompt,
            model_name=os.getenv('DEFAULT_LLM_MODEL', 'gemini-2.5-flash'),
            system_prompt=f'You are a medical translator. Translate medical text accurately to {lang_name}.'
        ))
        return JsonResponse({'explanation': result}, status=200)
    except Exception as e:
        logger.error(f'Explain result failed: {e}')
        return JsonResponse({'explanation': text, 'error': str(e)}, status=200)
