import secrets

@api_view(['POST'])
@permission_classes([IsAuthenticated])
@csrf_exempt
def generate_emergency_token(request):
    from .models import EmergencyToken
    try:
        patient = Patient.objects.get(user=request.user)
    except Patient.DoesNotExist:
        return JsonResponse({'error': 'Patient profile not found'}, status=404)
    EmergencyToken.objects.filter(patient=patient).update(is_active=False)
    token_str = secrets.token_urlsafe(32)
    EmergencyToken.objects.create(patient=patient, token=token_str, is_active=True)
    return JsonResponse({'token': token_str, 'url': f'/emergency/{token_str}'}, status=200)

@api_view(['DELETE'])
@permission_classes([IsAuthenticated])
@csrf_exempt
def revoke_emergency_token(request):
    from .models import EmergencyToken
    try:
        patient = Patient.objects.get(user=request.user)
    except Patient.DoesNotExist:
        return JsonResponse({'error': 'Patient profile not found'}, status=404)
    EmergencyToken.objects.filter(patient=patient).update(is_active=False)
    return JsonResponse({}, status=204)

@api_view(['GET'])
@permission_classes([])
def get_emergency_card(request, token):
    from .models import EmergencyToken
    try:
        et = EmergencyToken.objects.get(token=token, is_active=True)
    except EmergencyToken.DoesNotExist:
        return JsonResponse({'error': 'Invalid or expired token'}, status=404)
    patient = et.patient
    latest_prescription = patient.prescriptions.order_by('-created_at').first()
    active_meds = []
